export function normalizeLocale(value: string | null | undefined): SiteLocale {
  return value === "en" ? "en" : "ro";
}

export function translateText(text: string, locale: SiteLocale) {
  if (locale === "ro") {
    return text;
  }

  const exactTranslation = englishTranslations[text];

  if (exactTranslation) {
    return exactTranslation;
  }

  return englishPhraseTranslations.reduce(
    (nextText, [source, replacement]) => nextText.replaceAll(source, replacement),
    text,
  );
}
